with flattened as (select id, service, host, log_ts, latency_ms, key, v from app_logs lateral view explode(context) li as key, v) select date_trunc('hour', log_ts) as hour_window, host, stddev_samp(latency_ms) as latency_ms_stddev, (unix_timestamp(max(log_ts)) - unix_timestamp(min(log_ts))) / 60 as span_minutes, sort_array(collect_set(host)) as host_list from flattened group by grouping sets ((date_trunc('hour', log_ts), host), (date_trunc('hour', log_ts))) having latency_ms_stddev >= 0 order by latency_ms_stddev desc
